import type { PgDatabase, PgQueryResultHKT } from 'drizzle-orm/pg-core';
import type * as schema from './schema.js';

/** Injection token of the Drizzle database. */
export const databaseToken: unique symbol = Symbol('databaseToken');

/** Injection token of the underlying `pg` connection pool. */
export const pgPoolToken: unique symbol = Symbol('pgPoolToken');

/**
 * Drizzle database, independent of the driver (node-postgres in production, PGlite in tests).
 */
export type Database = PgDatabase<PgQueryResultHKT, typeof schema>;

/** Folder containing the SQL migrations generated by drizzle-kit. */
export const migrationsFolder: string = new URL('../../drizzle', import.meta.url).pathname;
